<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$labels=\NpmGateway\Services\RmCorrectionStatus::LABELS;$events=['submitted'=>'Submitted','more_information_needed'=>'More Information Needed','manager_responded'=>'Manager Responded','approved'=>'Approved','denied'=>'Denied'];?>
<section class="card gateway-detail-card" aria-labelledby="rm-details"><div class="card-body"><h2 id="rm-details">Request Details</h2><dl class="row gateway-review-record__fields"><dt class="col-sm-4">Property</dt><dd class="col-sm-8"><?=$e($request['property_name'])?></dd><dt class="col-sm-4">Lot / Address</dt><dd class="col-sm-8"><?=$e($request['lot_address'])?></dd><dt class="col-sm-4">Tenant</dt><dd class="col-sm-8"><?=$e($request['tenant_name'])?></dd><dt class="col-sm-4">Submitted By</dt><dd class="col-sm-8"><?=$e($request['submitted_by_name'])?></dd><dt class="col-sm-4">Submitted At</dt><dd class="col-sm-8"><?=$e((new DateTimeImmutable($request['submitted_at']))->format('F j, Y \a\t g:i A'))?></dd><dt class="col-sm-4">Current Status</dt><dd class="col-sm-8"><?=$e($labels[$request['status']])?></dd><dt class="col-sm-4">Last Updated</dt><dd class="col-sm-8"><?=$e((new DateTimeImmutable($request['updated_at']))->format('F j, Y \a\t g:i A'))?></dd></dl><h3>Correction Request</h3><p class="gateway-review-timeline__comments"><?=nl2br($e($request['correction_request']),false)?></p><?php $comments=array_values(array_filter($request['history'],fn($h)=>in_array($h['event_type'],['approved','denied','more_information_needed'],true)));if($comments!==[]):?><h3>Comments</h3><p><?=nl2br($e(end($comments)['comments']),false)?></p><?php endif;?></div></section>
<section class="gateway-review-timeline" aria-labelledby="rm-history"><h2 id="rm-history">History</h2><ol class="gateway-review-timeline__events"><?php foreach($request['history'] as $h):?><li class="gateway-review-timeline__event"><strong><?=$e($events[$h['event_type']]??'Update')?></strong><div class="gateway-review-timeline__meta"><time datetime="<?=$e((new DateTimeImmutable($h['created_at']))->format(DateTimeInterface::ATOM))?>"><?=$e((new DateTimeImmutable($h['created_at']))->format('F j, Y \a\t g:i A'))?></time><span><?=$e($h['actor_name'])?></span></div><?php if(($h['comments']??'')!==''):?><p class="gateway-review-timeline__comments"><?=nl2br($e($h['comments']),false)?></p><?php endif;?></li><?php endforeach;?></ol></section>
